import { test, expect, type APIRequestContext } from '@playwright/test';

const TINY_PNG = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
  'base64'
);

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function loginUser(
  request: APIRequestContext,
  email: string,
  nickname: string
): Promise<{ id: string; email: string; nickname: string }> {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status(), 'send-code 应返回 200').toBe(200);
  const sendJson = await sendRes.json();
  expect(sendJson.devCode).toMatch(/^\d{6}$/);

  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: sendJson.devCode, nickname },
  });
  expect(verifyRes.status(), 'verify-code 应返回 200').toBe(200);
  const verifyJson = await verifyRes.json();
  expect(verifyJson.ok).toBe(true);
  return verifyJson.user;
}

function parseRgb(colorStr: string): [number, number, number] {
  const match = /rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/i.exec(colorStr);
  if (!match) return [0, 0, 0];
  return [Number(match[1]), Number(match[2]), Number(match[3])];
}

function relativeLuminance([r, g, b]: [number, number, number]): number {
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255;
}

test.describe.serial('社区动态展示优化与深色模式支持 E2E 验收套件', () => {
  test('AC-1: feed 正文 @用户 无边框居中展示，官方认证使用 SVG 图标而非文字标签', async ({
    browser,
    page,
  }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const suffix = Date.now().toString().slice(-4);
    const peerNick = `协作同学${suffix}`;
    const peerCtx = await browser.newContext();
    try {
      await loginUser(peerCtx.request, makeEmail('ac1-peer'), peerNick);
    } finally {
      await peerCtx.close();
    }

    await loginUser(page.request, makeEmail('ac1-author'), `测试作者${suffix}`);
    const bodyText = `请 @${peerNick} 和 @官方反馈 一起确认居中与无边框展示-${suffix}`;
    const createRes = await page.request.post('/api/posts', {
      data: { content: bodyText },
    });
    expect(createRes.status()).toBe(201);

    await page.goto('/');
    const card = page.locator('article').filter({ hasText: bodyText }).first();
    await expect(card).toBeVisible({ timeout: 10000 });

    const normalMention = card.getByTestId('mention-tag').first();
    const officialMention = card.getByTestId('mention-tag-official').first();
    await expect(normalMention).toBeVisible();
    await expect(officialMention).toBeVisible();

    // 1) 验证 @用户名 无边框、无阴影框、无底色框
    for (const loc of [normalMention, officialMention]) {
      const styles = await loc.evaluate((el) => {
        const st = window.getComputedStyle(el);
        return {
          borderWidth: st.borderTopWidth,
          boxShadow: st.boxShadow,
          backgroundColor: st.backgroundColor,
          alignItems: st.alignItems,
          verticalAlign: st.verticalAlign,
        };
      });
      expect(styles.borderWidth).toBe('0px');
      expect(styles.boxShadow).toBe('none');
      expect(styles.backgroundColor).toBe('rgba(0, 0, 0, 0)');
      expect(styles.alignItems).toBe('center');
      expect(styles.verticalAlign).toBe('middle');
    }

    // 2) 验证官方认证徽章为 SVG 图标且不包含文字标签
    const badge = officialMention.getByTestId('official-badge');
    await expect(badge).toBeVisible();
    await expect(badge.locator('svg')).toBeVisible();
    const badgeText = (await badge.innerText()).trim();
    expect(badgeText).toBe('');

    // 3) 验证 @官方反馈 文本与官方图标垂直居中对齐
    const alignmentDiff = await officialMention.evaluate((el) => {
      const textSpan = el.querySelector('span');
      const badgeEl = el.querySelector('[data-testid="official-badge"]');
      if (!textSpan || !badgeEl) return 999;
      const r1 = textSpan.getBoundingClientRect();
      const r2 = badgeEl.getBoundingClientRect();
      const c1 = r1.top + r1.height / 2;
      const c2 = r2.top + r2.height / 2;
      return Math.abs(c1 - c2);
    });
    expect(alignmentDiff).toBeLessThanOrEqual(3);

    // 4) 验证详情弹窗中同样保持无框与图标认证
    await card.click();
    const dialog = page.getByRole('dialog').first();
    await expect(dialog).toBeVisible({ timeout: 10000 });
    const dialogOfficialMention = dialog.getByTestId('mention-tag-official').first();
    await expect(dialogOfficialMention).toBeVisible();
    await expect(dialogOfficialMention.getByTestId('official-badge').locator('svg')).toBeVisible();

    expect(pageErrors, 'AC-1 不应产生前端异常').toEqual([]);
  });

  test('AC-2: 全局支持 light/dark 模式切换、持久化且深色模式下对比度正常无反色异常', async ({
    page,
  }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    await loginUser(page.request, makeEmail('ac2-theme'), '主题体验官');
    const themePostText = `深色模式对比度校验动态-${Date.now()}`;
    const postRes = await page.request.post('/api/posts', {
      data: { content: themePostText },
    });
    expect(postRes.status()).toBe(201);

    await page.goto('/');
    const card = page.locator('article').filter({ hasText: themePostText }).first();
    await expect(card).toBeVisible({ timeout: 10000 });

    // 初始应为 light 模式（无 .dark 类）
    await expect(page.locator('html')).not.toHaveClass(/\bdark\b/);

    // 切换至深色模式
    const toggleBtn = page.getByTestId('theme-toggle');
    await expect(toggleBtn).toBeVisible();
    await toggleBtn.click();

    await expect(page.locator('html')).toHaveClass(/\bdark\b/);
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark');

    // 验证页面背景、卡片背景与正文文字在深色模式下具备高可读性对比度（无反色异常）
    const darkPalette = await page.evaluate(() => {
      const bodyStyle = window.getComputedStyle(document.body);
      const article = document.querySelector('article');
      const articleStyle = article ? window.getComputedStyle(article) : null;
      const bodyParagraph = article?.querySelector('p');
      const pStyle = bodyParagraph ? window.getComputedStyle(bodyParagraph) : null;
      return {
        stored: window.localStorage.getItem('dev-community-theme'),
        bodyBg: bodyStyle.backgroundColor,
        bodyColor: bodyStyle.color,
        articleBg: articleStyle?.backgroundColor ?? '',
        textColor: pStyle?.color ?? '',
      };
    });

    expect(darkPalette.stored).toBe('dark');
    expect(relativeLuminance(parseRgb(darkPalette.bodyBg))).toBeLessThan(0.2);
    expect(relativeLuminance(parseRgb(darkPalette.articleBg))).toBeLessThan(0.25);
    expect(relativeLuminance(parseRgb(darkPalette.bodyColor))).toBeGreaterThan(0.7);
    expect(relativeLuminance(parseRgb(darkPalette.textColor))).toBeGreaterThan(0.65);

    // 刷新页面后深色模式保持持久化
    await page.reload();
    await expect(page.locator('html')).toHaveClass(/\bdark\b/);
    await expect(page.locator('article').filter({ hasText: themePostText }).first()).toBeVisible({
      timeout: 10000,
    });

    // 切换回浅色模式
    await page.getByTestId('theme-toggle').click();
    await expect(page.locator('html')).not.toHaveClass(/\bdark\b/);
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'light');

    const lightPalette = await page.evaluate(() => {
      const bodyStyle = window.getComputedStyle(document.body);
      const article = document.querySelector('article');
      const p = article?.querySelector('p');
      return {
        bodyBg: bodyStyle.backgroundColor,
        textColor: p ? window.getComputedStyle(p).color : '',
      };
    });
    expect(relativeLuminance(parseRgb(lightPalette.bodyBg))).toBeGreaterThan(0.85);
    expect(relativeLuminance(parseRgb(lightPalette.textColor))).toBeLessThan(0.35);

    // 移动端切换按钮也应正常可用且无横向溢出
    await page.setViewportSize({ width: 375, height: 812 });
    const mobileToggle = page.getByTestId('mobile-theme-toggle');
    await expect(mobileToggle).toBeVisible();
    await mobileToggle.click();
    await expect(page.locator('html')).toHaveClass(/\bdark\b/);

    expect(pageErrors, 'AC-2 不应产生前端异常').toEqual([]);
  });

  test('AC-3: 无图动态包含 URL 时渲染图文预览卡片且支持直接跳转，有图或纯文本不误渲染', async ({
    page,
  }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    await loginUser(page.request, makeEmail('ac3-link'), '链接预览测试员');

    const targetUrl = `https://developers.cloudflare.com/d1/get-started/?v=${Date.now().toString().slice(-4)}`;
    const linkPostText = `推荐这份 Cloudflare D1 入门文档 ${targetUrl} 非常清晰`;
    const plainPostText = `这是一条纯文本动态，没有任何链接和配图-${Date.now()}`;
    const imageWithUrlText = `已配图的动态带链接 ${targetUrl} 不应重复展示链接卡-${Date.now()}`;

    // 上传测试图片用于有图对比用例
    const uploadRes = await page.request.post('/api/uploads', {
      multipart: {
        file: {
          name: 'preview-check.png',
          mimeType: 'image/png',
          buffer: TINY_PNG,
        },
      },
    });
    expect(uploadRes.status()).toBe(201);
    const uploadJson = await uploadRes.json();

    const r1 = await page.request.post('/api/posts', { data: { content: linkPostText } });
    const r2 = await page.request.post('/api/posts', { data: { content: plainPostText } });
    const r3 = await page.request.post('/api/posts', {
      data: { content: imageWithUrlText, imageUrl: uploadJson.url },
    });
    expect(r1.status()).toBe(201);
    expect(r2.status()).toBe(201);
    expect(r3.status()).toBe(201);

    await page.goto('/');

    // 1) 无图含 URL 动态成功渲染可点击跳转的预览卡片
    const linkCardPost = page.locator('article').filter({ hasText: linkPostText }).first();
    await expect(linkCardPost).toBeVisible({ timeout: 10000 });
    const previewCard = linkCardPost.getByTestId('link-preview-card');
    await expect(previewCard).toBeVisible();
    await expect(previewCard).toHaveAttribute('href', targetUrl);
    await expect(previewCard).toHaveAttribute('target', '_blank');
    await expect(previewCard).toHaveAttribute('rel', /noopener/);
    await expect(previewCard).toContainText('developers.cloudflare.com');
    await expect(linkCardPost).toContainText('推荐这份 Cloudflare D1 入门文档');
    await expect(linkCardPost).toContainText('非常清晰');

    // 2) 纯文本动态不渲染链接预览卡片
    const plainPost = page.locator('article').filter({ hasText: plainPostText }).first();
    await expect(plainPost).toBeVisible();
    await expect(plainPost.getByTestId('link-preview-card')).toHaveCount(0);

    // 3) 有图动态优先展示图片，不重复渲染链接预览卡片
    const imagePost = page.locator('article').filter({ hasText: imageWithUrlText }).first();
    await expect(imagePost).toBeVisible();
    await expect(imagePost.locator(`img[src="${uploadJson.url}"]`)).toBeVisible();
    await expect(imagePost.getByTestId('link-preview-card')).toHaveCount(0);

    // 4) 打开动态详情弹窗，同样展示链接预览卡片
    await linkCardPost.getByText('非常清晰').click();
    const dialog = page.getByRole('dialog').first();
    await expect(dialog).toBeVisible({ timeout: 10000 });
    const dialogPreview = dialog.getByTestId('link-preview-card');
    await expect(dialogPreview).toBeVisible();
    await expect(dialogPreview).toHaveAttribute('href', targetUrl);
    await dialog.getByRole('button', { name: '关闭弹窗' }).click();
    await expect(dialog).toHaveCount(0);

    // 5) 移动端 (375px) 预览卡片不引发横向溢出
    await page.setViewportSize({ width: 375, height: 812 });
    const overflow = await page.evaluate(
      () => document.documentElement.scrollWidth - window.innerWidth
    );
    expect(overflow).toBeLessThanOrEqual(2);

    expect(pageErrors, 'AC-3 不应产生前端异常').toEqual([]);
  });
});
